x,y,z,s,t,r,u,v,w,p,q,a,b,c,th=S.symbols('x y z s t r u v w p q alpha beta gamma theta',real=True)
la=lambda e:S.latex(S.simplify(e));pair=lambda k,e:dict(ko=k,en=e)
def add(n,st,sk,se,ak,ae,ck,ce,parts=[]):
 pg=1029 if n<=17 else 1030 if n<=41 else 1031 if n<=56 else 1032
 E.append(dict(id=f'stewart9-exercise-14.5-{n}',number=n,subparts=parts,source=dict(printedPage=pg,pdfPage=pg+37),topic=pair('연쇄법칙과 음함수미분','Chain rule and implicit differentiation'),statement=pair(*st),hint=pair('각 의존 경로의 미분을 곱하고 모든 경로를 더한다.','Multiply derivatives along each dependency path, then sum all paths.'),steps=pair(sk,se),answer=pair(ak,ae),check=pair(ck,ce),conceptHref='../s14-5.html',status='math-verified'))
def chain(n,name,F,vars,subs,outer,point=None,both=False):
 mapping=dict(zip(vars,subs));comp=F.subs(mapping,simultaneous=True);der=[];sk=[];se=[]
 for var in outer:
  terms=[S.diff(F,j).subs(mapping,simultaneous=True)*S.diff(k,var) for j,k in zip(vars,subs)];d=S.simplify(sum(terms));direct=S.diff(comp,var);assert S.simplify(d-direct)==0
  eq=' + '.join('('+la(term)+')' for term in terms)
  sk.append(f'\\({name}_{la(var)}={eq}={la(d)}\\).');se.append(f'\\({name}_{la(var)}={eq}={la(d)}\\).')
  der.append(S.simplify(d.subs(point)) if point else d)
 data=',\\quad '.join(la(j)+'='+la(k) for j,k in zip(vars,subs));goal=','.join(la(v) for v in outer)
 st=(f'\\({name}={la(F)};\quad {data}\\). {goal}에 대한 미분을 '+('두 방법(연쇄법칙, 직접 대입)으로 구하라.' if both else '연쇄법칙으로 구하라.'),f'\\({name}={la(F)};\quad {data}\\). Find derivatives with respect to {goal} '+('by both chain rule and direct substitution.' if both else 'by the chain rule.'))
 if point:ps=', '.join(la(j)+'='+la(vv) for j,vv in point.items());st=(st[0]+f' \\({ps}\\)에서 평가하라.',st[1]+f' Evaluate at \\({ps}\\).')
 if both:sk.append(f'직접 대입식은 \\({name}={la(comp)}\\). 이를 미분하면 같은 결과이다.');se.append(f'Direct substitution gives \\({name}={la(comp)}\\); differentiating yields the same result.')
 if point:sk.append('마지막에 지정된 기준점 값을 대입한다.');se.append('Finally substitute the specified evaluation point.')
 ans='\\('+',\\quad '.join(name+'_{'+la(var)+'}='+la(d) for var,d in zip(outer,der))+'\\).'
 add(n,st,sk,se,ans,ans,'합성함수를 먼저 대입한 뒤 기호 미분한 결과와 연쇄법칙 결과의 차이가0임을 검사했다. 식은 원래 함수와 모든 미분이 정의되는 영역에서 적용한다.','Symbolic differentiation after direct substitution agrees identically with the chain-rule result. Use the formulas where the original functions and derivatives are defined.')
rows=[(1,'z',x*x*y+x*y*y,[x,y],[3*t,t*t],[t],True),(2,'z',x*y*S.exp(y),[x,y],[t*t,5*t],[t],True),(3,'z',x*y**3-x*x*y,[x,y],[t*t+1,t*t-1],[t],False),(4,'z',(x-y)/(x+2*y),[x,y],[S.exp(S.pi*t),S.exp(-S.pi*t)],[t],False),(5,'z',S.sin(x)*S.cos(y),[x,y],[S.sqrt(t),1/t],[t],False),(6,'z',S.sqrt(1+x*y),[x,y],[S.tan(t),S.atan(t)],[t],False),(7,'w',x*S.exp(y/z),[x,y,z],[t*t,1-t,1+2*t],[t],False),(8,'w',S.log(S.sqrt(x*x+y*y+z*z)),[x,y,z],[S.sin(t),S.cos(t),S.tan(t)],[t],False),(9,'z',x*x+y*y,[x,y],[2*s+3*t,s+t],[s,t],True),(10,'z',x*x*S.sin(y),[x,y],[s*s*t,s*t],[s,t],True),(11,'z',(x-y)**5,[x,y],[s*s*t,s*t*t],[s,t],False),(12,'z',S.atan(x*x+y*y),[x,y],[s*S.log(t),t*S.exp(s)],[s,t],False),(13,'z',S.log(3*x+2*y),[x,y],[s*S.sin(t),t*S.cos(s)],[s,t],False),(14,'z',S.sqrt(x)*S.exp(x*y),[x,y],[1+s*t,s*s-t*t],[s,t],False),(15,'z',S.sin(th)/r,[r,th],[s*t,s*s+t*t],[s,t],False),(16,'z',S.tan(u/v),[u,v],[2*s+3*t,3*s-2*t],[s,t],False)]
